const actionsRef = React.useRef<Menu.Root.Actions>(null);

<Menu.Root actionsRef={actionsRef}>
  <Menu.Trigger>Open</Menu.Trigger>
  <Menu.Portal>
    <Menu.Positioner>
      <Menu.Popup
        onKeyDown={(event) => {
          if (event.ctrlKey && event.key === 'j') {
            event.preventDefault();
            actionsRef.current?.highlightItem('next');
          }
        }}
      >
        {/* items */}
      </Menu.Popup>
    </Menu.Positioner>
  </Menu.Portal>
</Menu.Root>;

